import 'dart:io';import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:firebase_storage/firebase_storage.dart';class ProductService{final _db=FirebaseFirestore.instance;final _auth=FirebaseAuth.instance;Future<List<String>> uploadImages(List<File> files,String id)async{final out=<String>[];for(var i=0;i<files.length;i++){final r=FirebaseStorage.instance.ref('products/'+_auth.currentUser!.uid+'/'+id+'/'+i.toString()+'.jpg');await r.putFile(files[i]);out.add(await r.getDownloadURL());}return out;}Future<void> createProduct({required String title,required String description,required int price,required List<File> images,required double latitude,required double longitude,String category='Lainnya',String locationName=''})async{final uid=_auth.currentUser!.uid,ref=_db.collection('products').doc();final user=await _db.collection('users').doc(uid).get();final urls=await uploadImages(images,ref.id);await ref.set({'sellerId':uid,'sellerName':user.data()?['name']??user.data()?['email']??'Pengguna Flowa','title':title.trim(),'description':description.trim(),'price':price,'imageUrl':urls.isEmpty?'':urls.first,'imageUrls':urls,'latitude':latitude,'longitude':longitude,'locationName':locationName,'category':category,'status':'active','reportCount':0,'createdAt':FieldValue.serverTimestamp(),'updatedAt':FieldValue.serverTimestamp()});}Future<void> deleteProduct(String id,List<dynamic> urls)async{for(final u in urls){try{await FirebaseStorage.instance.refFromURL(u.toString()).delete();}catch(_){}}await _db.collection('products').doc(id).delete();}Future<void> report(String id,String reason)async{await _db.collection('reports').add({'productId':id,'reason':reason,'reporterId':_auth.currentUser?.uid,'status':'open','createdAt':FieldValue.serverTimestamp()});await _db.collection('products').doc(id).update({'reportCount':FieldValue.increment(1)});}}